            click.style(" ".join(f"{h:{w}}" for h, w in zip(headers, widths)).rstrip(),
                        bold=True)
        )
        click.echo(" ".join("-" * w for w in widths))
        for row in rows:
            click.echo(" ".join(f"{c:{w}}" for c, w in zip(row, widths)).rstrip())

